import{_ as e,o as t,c as i,a3 as r}from"./chunks/framework.CZBGEXos.js";const u=JSON.parse('{"title":"Capacitaciones (Art. 16)","description":"","frontmatter":{},"headers":[],"relativePath":"ds44/capacitaciones.md","filePath":"ds44/capacitaciones.md"}'),s={name:"ds44/capacitaciones.md"};function o(d,a,n,c,l,p){return t(),i("div",null,[...a[0]||(a[0]=[r(`<h1 id="capacitaciones-art-16" tabindex="-1">Capacitaciones (Art. 16) <a class="header-anchor" href="#capacitaciones-art-16" aria-label="Permalink to &quot;Capacitaciones (Art. 16)&quot;">​</a></h1><p>El DS 44, en línea con el <strong>Artículo 16</strong>, obliga a las empresas a <strong>informar y capacitar</strong> oportuna y convenientemente a sus trabajadores sobre los riesgos de sus labores, las medidas preventivas y los métodos de trabajo correctos. Toda capacitación debe quedar <strong>registrada y firmada</strong>.</p><h2 id="tipos-de-actividad-formativa" tabindex="-1">Tipos de actividad formativa <a class="header-anchor" href="#tipos-de-actividad-formativa" aria-label="Permalink to &quot;Tipos de actividad formativa&quot;">​</a></h2><p>Build &amp; Serve gestiona estas actividades a través del módulo de <a href="/manual/modulos/actividades.html">Actividades</a>, con el campo <code>tipo</code>:</p><table tabindex="0"><thead><tr><th>Tipo</th><th>Código</th><th>Duración / Frecuencia</th><th>Descripción</th></tr></thead><tbody><tr><td>Charla de 5 minutos</td><td><code>CHARLA_5MIN</code></td><td>Diaria</td><td>Charla preventiva breve antes de iniciar la jornada</td></tr><tr><td>Inducción</td><td><code>INDUCCION</code></td><td>Al ingreso</td><td>Inducción de seguridad para nuevos trabajadores</td></tr><tr><td>Capacitación SST</td><td><code>CAPACITACION</code></td><td>8 horas (Art. 16)</td><td>Capacitación formal obligatoria sobre riesgos y prevención</td></tr><tr><td>Análisis de Riesgo del Trabajo</td><td><code>ART</code></td><td>Por tarea crítica</td><td>Identificación de riesgos antes de una actividad específica</td></tr></tbody></table><h2 id="capacitacion-obligatoria-de-8-horas" tabindex="-1">Capacitación obligatoria de 8 horas <a class="header-anchor" href="#capacitacion-obligatoria-de-8-horas" aria-label="Permalink to &quot;Capacitación obligatoria de 8 horas&quot;">​</a></h2><p>La capacitación formal del Art. 16 contempla un mínimo de <strong>8 horas</strong>. En la plataforma queda como un documento <code>CAPACITACION_SST</code> con:</p><ul><li><strong>Relator</strong>: persona que dicta la capacitación (<code>relatorId</code>).</li><li><strong>Temario</strong>: contenidos tratados.</li><li><strong>Asistentes</strong>: lista de trabajadores con su firma individual.</li><li><strong>Firma del relator</strong>: certifica que la capacitación se realizó.</li></ul><h2 id="flujo-de-registro-y-firma" tabindex="-1">Flujo de registro y firma <a class="header-anchor" href="#flujo-de-registro-y-firma" aria-label="Permalink to &quot;Flujo de registro y firma&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Prevencionista programa la actividad (estado: programada)</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>2. Se realiza la capacitación (estado: en_curso)</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>3. Cada asistente firma su asistencia (PIN o presencial)</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>4. El relator firma como responsable de la actividad</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>5. La actividad queda completada con registro inmutable</span></span></code></pre></div><h2 id="firma-cruzada-del-relator" tabindex="-1">Firma cruzada del relator <a class="header-anchor" href="#firma-cruzada-del-relator" aria-label="Permalink to &quot;Firma cruzada del relator&quot;">​</a></h2><p>Las capacitaciones (<code>CAPACITACION_SST</code>) y charlas (<code>CHARLA_5MIN</code>) usan <strong>firma cruzada</strong>: no basta con la asistencia del trabajador, también se requiere la firma del relator que valida que la actividad efectivamente se impartió. Esto refuerza la trazabilidad ante fiscalización.</p><p>Ver el detalle del mecanismo en <a href="/manual/modulos/firmas.html">Firmas</a>.</p><div class="tip custom-block"><p class="custom-block-title">Certificados de asistencia</p><p>A partir del registro firmado, la plataforma puede generar constancias de asistencia por trabajador, útiles para acreditar el cumplimiento del Art. 16 ante la mutualidad o la Dirección del Trabajo.</p></div>`,14)])])}const h=e(s,[["render",o]]);export{u as __pageData,h as default};
